"""Reusable native Bundle subgroups; no per-object or per-fixture trees."""
import bpy
from .path_surface_nodes import _Nodes

SURFACE = 'Prochitecture Streets / Dynamic Bundle surface v1'
CONTACT = 'Prochitecture Streets / Continuous Bundle centerline guard v1'


def _interface(tree, sockets, direction='INPUT'):
    for name, kind in sockets:
        tree.interface.new_socket(name=name, in_out=direction, socket_type='NodeSocket'+kind)


def surface(*, free_terminal_alignment=False, regular_sampling=False,event_sampling=False, free_cap_body=False, free_caps=False,
            balanced_overlap_band=False, local_terminal_chart=False,narrow_terminal_caps=False,finite_terminal_contact=False,
            uniform_separated=False, uniform_mixed=False, independent_terminal_charts=False, independent_free_caps=False):
    if independent_free_caps and not (independent_terminal_charts and finite_terminal_contact):
        raise ValueError('Independent free caps require independent charts and finite terminal caps')
    if independent_terminal_charts and not (local_terminal_chart and uniform_mixed):
        raise ValueError('Independent terminal charts require local charts and exact mixed row sampling')
    if uniform_mixed and not uniform_separated:
        raise ValueError('Exact mixed rows require the uniform control/event-anchor construction')
    if uniform_separated and not event_sampling:
        raise ValueError('Uniform separated bands require event-aware certified row sampling')
    if balanced_overlap_band and not event_sampling:
        raise ValueError('Overlap-band balancing requires physical event rows')
    if local_terminal_chart and not (free_caps and event_sampling):
        raise ValueError('Local terminal charts require physical free-end cuts and event-row sampling')
    if narrow_terminal_caps and not (free_caps and event_sampling):
        raise ValueError('Narrow terminal caps require physical free-end cuts and event-row sampling')
    if finite_terminal_contact and not narrow_terminal_caps:
        raise ValueError('Finite terminal contact requires narrow terminal caps')
    if free_caps:free_cap_body=True
    if free_cap_body:free_terminal_alignment=True
    if event_sampling:regular_sampling=True
    name=SURFACE+' / Independent free terminal frames v1' if free_terminal_alignment else SURFACE
    if regular_sampling:name+=' / Certified regular rows v1'
    if event_sampling:name+=' / Local event anchors v2'
    if free_caps:name+=' / Profiled conforming free caps v2'
    elif free_cap_body:name+=' / PRIVATE clipped internal body only v1'
    if balanced_overlap_band:name+=' / Balanced overlap band v1'
    if local_terminal_chart:name+=' / Local terminal chart v2'
    if narrow_terminal_caps:name+=' / Narrow terminal caps v1'
    if finite_terminal_contact:
        # Keep this below Blender's datablock-name limit; feature flags below
        # carry the full contract instead of an ever-growing name suffix.
        name=SURFACE+' / Finite narrow caps and local events v1'
    if uniform_separated:
        flags=(free_terminal_alignment,regular_sampling,event_sampling,free_cap_body,free_caps,
               balanced_overlap_band,local_terminal_chart,narrow_terminal_caps,finite_terminal_contact)
        configuration=sum(int(bool(flag))<<i for i,flag in enumerate(flags))
        name=f'Prochitecture Streets / Uniform Bundle rows v{10 if independent_free_caps else 8 if independent_terminal_charts else 7 if uniform_mixed else 5} / {configuration:03x}'
    tree = bpy.data.node_groups.get(name)
    if tree:
        return tree
    from . import bundle_surface_nodes
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree')
    _interface(tree, [('Curves', 'Geometry'), ('Stations', 'Geometry'), ('Owner', 'Int'),
        ('Partner', 'Int'), ('Rows', 'Int'), ('Transverse', 'Int'), ('Target Cell', 'Float'),
        ('Radial Samples', 'Int'), ('Cell Size', 'Float'), ('Mesh Resolution', 'Int'),
        ('Height Exaggeration', 'Float'), ('Minimum Separator Width', 'Float'),
        ('Material', 'Material'), ('Grass Material', 'Material')])
    _interface(tree, [('Geometry', 'Geometry'), ('Valid', 'Bool'), ('Code', 'Int'), ('Position', 'Vector')], 'OUTPUT')
    g = _Nodes(tree)
    inp = g.node('NodeGroupInput', 'One ordered Bundle and shared controls')
    out = g.node('NodeGroupOutput', 'One pavement union and automatic separators')
    result = bundle_surface_nodes.construct(g, inp.outputs['Curves'], inp.outputs['Owner'],
        inp.outputs['Partner'], inp, inp.outputs['Target Cell'], inp.outputs['Transverse'],
        inp.outputs['Stations'], inp.outputs['Rows'],free_terminal_alignment=free_terminal_alignment,
        regular_sampling=regular_sampling,event_sampling=event_sampling,free_cap_body=free_cap_body,free_caps=free_caps,
        balanced_overlap_band=balanced_overlap_band, local_terminal_chart=local_terminal_chart,
        narrow_terminal_caps=narrow_terminal_caps,finite_terminal_contact=finite_terminal_contact,
        uniform_separated=uniform_separated,uniform_mixed=uniform_mixed,
        independent_terminal_charts=independent_terminal_charts,independent_free_caps=independent_free_caps)
    for name, value in zip(('Geometry', 'Valid', 'Code', 'Position'), result):
        g.set(value, out.inputs[name])
    if regular_sampling:tree['st_bundle_regular_sampling']=1
    if uniform_separated:
        tree['st_bundle_uniform_separated']=5
        tree['st_bundle_uniform_smooth_tiles']=1
        tree['st_bundle_uniform_smooth_terminals']=1
        tree['st_bundle_physical_row_balance']=1
    if uniform_mixed:tree['st_bundle_uniform_mixed']=2
    if event_sampling:tree['st_bundle_event_sampling']=2
    if balanced_overlap_band:tree['st_bundle_balanced_overlap_band']=1
    if local_terminal_chart:tree['st_bundle_local_terminal_chart']=3 if independent_terminal_charts else 2
    if independent_terminal_charts:tree['st_bundle_independent_terminal_charts']=1
    if independent_free_caps:tree['st_bundle_independent_free_caps']=2
    if narrow_terminal_caps:tree['st_bundle_narrow_terminal_caps']=1
    if finite_terminal_contact:
        tree['st_bundle_finite_terminal_contact']=1
        tree['st_bundle_local_difference_events']=1
    if free_caps:tree['st_bundle_profiled_free_caps']=2
    elif free_cap_body:tree['st_bundle_incomplete_body_only']=True
    return tree


def with_saved_smooth_tiles(original):
    """Small private-library upgrade equivalent to the canonical v3 builder.

    Reuses the saved field program, changing only smooth refinement anchors.
    This avoids rebuilding thousands of unchanged nodes for an experiment.
    """
    from .bundle_axis_nodes import _smooth_macro_anchors
    if original.get('st_bundle_uniform_separated')!=2:
        raise ValueError('Expected the v2 experimental separated-Bundle primitive')
    tree=original.copy();tree.name=original.name.replace(' v2 /',' v3 /')
    g=_Nodes(tree)
    inp=next(n for n in tree.nodes if n.type=='GROUP_INPUT')
    controls,=[n for n in tree.nodes if n.type=='SEPARATE_GEOMETRY'
               and n.label.startswith('Every original exact-member control retained')]
    line,=[n for n in tree.nodes if n.label=='Final physical Bundle station']
    store,=[link.to_node for link in line.outputs['Mesh'].links if link.to_node.type=='STORE_NAMED_ATTRIBUTE'
            and link.to_node.inputs['Name'].default_value=='st_bundle_metric']
    length,=[link.from_socket for link in store.inputs['Value'].links]
    source=controls.outputs['Selection'];destinations=[link.to_socket for link in source.links]
    smooth=g.all(*(g.compare(g.sample(inp.outputs['Curves'],g.named('st_sweep_interpolation','INT'),
        inp.outputs[key],'INT','CURVE'),3,kind='INT') for key in ('Owner','Partner')))
    selected=g.switch(smooth,source,_smooth_macro_anchors(g,length,inp.outputs['Target Cell']),'GEOMETRY',
        'Exact control anchors or coarse smooth refinement intervals')
    for socket in destinations:
        for link in list(socket.links):
            if link.from_socket==source:tree.links.remove(link)
        g.set(selected,socket)
    tree['st_bundle_uniform_separated']=3;tree['st_bundle_uniform_smooth_tiles']=1
    return tree


def with_saved_smooth_terminals(original):
    """Extend v3 sampling to certified smooth free-terminal charts.

    Only two sampling eligibility inputs change. Mapping admission, original
    chart anchors, all-knot certification and final acceptance stay intact.
    """
    if original.get('st_bundle_uniform_separated')!=3:
        raise ValueError('Expected the v3 experimental separated-Bundle primitive')
    tree=original.copy();tree.name=original.name.replace(' v3 /',' v4 /')
    g=_Nodes(tree)
    inp=next(n for n in tree.nodes if n.type=='GROUP_INPUT')
    attribute,=[n for n in tree.nodes if n.type=='STORE_NAMED_ATTRIBUTE'
                and n.inputs['Name'].default_value=='st_bundle_terminal_alignment']
    alignment,=[link.from_socket for link in attribute.inputs['Value'].links]
    # The other negated-alignment consumers admit the chart or certify the
    # original mapping; none of those may change. The v3 sampling predicates
    # are the two direct NOT -> AND consumers, each with one outgoing link.
    candidates=[]
    for link in list(alignment.links):
        negation=link.to_node
        if negation.bl_idname!='FunctionNodeBooleanMath' or negation.operation!='NOT':continue
        consumers=list(negation.outputs[0].links)
        if len(consumers)!=1:continue
        target=consumers[0].to_node
        if target.bl_idname=='FunctionNodeBooleanMath' and target.operation=='AND':
            candidates.append(consumers[0].to_socket)
    assert len(candidates)==2,'Unexpected terminal sampling predicate structure'
    direct_geometry_switches=[s for s in candidates if any(l.to_node.bl_idname=='GeometryNodeSwitch'
        and l.to_node.input_type=='GEOMETRY' for l in s.node.outputs[0].links)]
    assert len(direct_geometry_switches)==1,'Could not identify the row sampling predicate'
    smooth=g.all(*(g.compare(g.sample(inp.outputs['Curves'],g.named('st_sweep_interpolation','INT'),
        inp.outputs[key],'INT','CURVE'),3,kind='INT') for key in ('Owner','Partner')))
    for socket in candidates:
        prior,=[link.from_socket for link in socket.links]
        g.set(g.either(smooth,prior),socket)
    tree['st_bundle_uniform_separated']=4
    tree['st_bundle_uniform_smooth_terminals']=1
    return tree


def contact():
    tree = bpy.data.node_groups.get(CONTACT)
    if tree:
        return tree
    from . import bundle_contact_nodes
    tree = bpy.data.node_groups.new(CONTACT, 'GeometryNodeTree')
    _interface(tree, [('Curves', 'Geometry'), ('Sources', 'Geometry'), ('Paths', 'Geometry'),
                     ('Owner', 'Int'), ('Partner', 'Int')])
    _interface(tree, [('Valid', 'Bool'), ('Code', 'Int'), ('Position', 'Vector')], 'OUTPUT')
    g = _Nodes(tree)
    inp = g.node('NodeGroupInput', 'Authored and interpolated member centerlines')
    out = g.node('NodeGroupOutput', 'Continuous contact diagnosis')
    result = bundle_contact_nodes.check(g, inp.outputs['Curves'], inp.outputs['Owner'],
        inp.outputs['Partner'], sources=inp.outputs['Sources'], paths=inp.outputs['Paths'])
    for name in ('Valid', 'Code', 'Position'):
        g.set(result[name.lower()], out.inputs[name])
    return tree


def construct(g, curves, owner, partner, inp, target_cell, transverse, stations, ny, sources, paths):
    result = g.node('GeometryNodeGroup', 'Shared automatic Bundle surface')
    result.node_tree = surface()
    for name, value in [('Curves', curves), ('Stations', stations), ('Owner', owner),
                        ('Partner', partner), ('Rows', ny), ('Transverse', transverse), ('Target Cell', target_cell)]:
        g.set(value, result.inputs[name])
    for name in ('Radial Samples', 'Cell Size', 'Mesh Resolution', 'Height Exaggeration',
                 'Minimum Separator Width', 'Material', 'Grass Material'):
        g.set(inp.outputs[name], result.inputs[name])
    guard = g.node('GeometryNodeGroup', 'Shared continuous Bundle centerline check')
    guard.node_tree = contact()
    for name, value in [('Curves', curves), ('Sources', sources), ('Paths', paths), ('Owner', owner), ('Partner', partner)]:
        g.set(value, guard.inputs[name])
    return result.outputs, guard.outputs
